import math

aim_f = 0.0
phase = 'rev'
last_print = -10

def wrap(a):
    while a > 180: a -= 360
    while a < -180: a += 360
    return a

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def control(obs):
    global aim_f, phase, last_print
    hitch = obs.get('hitch_deg', 0.0) or 0.0
    rig = obs.get('rig', {}) or {}
    th = rig.get('trailer_heading_deg', -hitch)
    rear_dir = 180.0 + th
    look = -23
    if phase == 'fwd':
        if abs(hitch) < 8:
            phase = 'rev'
        else:
            return (0.0, 1.0, look)
    if abs(hitch) > 48:
        phase = 'fwd'
        return (0.0, 1.0, look)
    aim = None
    close = False
    try:
        cam = (obs.get('views', {}) or {}).get('camera')
        if cam:
            ox, oy = cam.get('origin', [0, 0])
            corners = cam.get('target_corners') or []
            pts = []
            for c in corners:
                b, d = c[0], c[1]
                pts.append((ox + d*math.cos(math.radians(b)), oy + d*math.sin(math.radians(b))))
            if len(pts) >= 2:
                cx = sum(p[0] for p in pts)/len(pts)
                cy = sum(p[1] for p in pts)/len(pts)
                b = math.degrees(math.atan2(cy-oy, cx-ox))
                dist = math.hypot(cx-ox, cy-oy)
                aim = wrap(rear_dir - b)
                if dist < 2.5:
                    close = True
            else:
                walls = cam.get('walls') or []
                rels = []
                for w in walls:
                    rels.append((wrap(w[0] - rear_dir), w[1]))
                best = None
                for a in range(-60, 61, 3):
                    cl = 9.0
                    for r, d in rels:
                        if abs(r - a) <= 10:
                            cl = min(cl, d)
                    score = cl - 0.02*abs(a)
                    if best is None or score > best[0]:
                        best = (score, a)
                if best is not None:
                    aim = -best[1]
    except Exception as e:
        aim = None
    if aim is not None:
        aim_f = 0.7*aim_f + 0.3*aim
    gain = 0.5 if close else 1.0
    target = clamp(gain*aim_f, -30, 30)
    steer = -0.75*target + 1.8*(hitch - target)
    steer = clamp(steer, -34, 34)
    t = obs.get('t', 0)
    if t - last_print > 2:
        last_print = t
        print('t=%.1f hitch=%.1f aim=%.1f tgt=%.1f steer=%.1f' % (t, hitch, aim_f, target, steer))
    return (steer, -1.0, look)

