import math

phase='fwd'
fwd_dist=0.0
aim_f=0.0
last_print=-10

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(x,lo,hi):
    return max(lo,min(hi,x))

def control(obs):
    global phase,fwd_dist,aim_f,last_print
    hitch=obs.get('hitch_deg',0.0) or 0.0
    dt=obs.get('dt',0.1) or 0.1
    mot=obs.get('motion',{}) or {}
    v=mot.get('v_mps',0.0) or 0.0
    look=-23
    t=obs.get('t',0)
    if phase=='fwd':
        fwd_dist+=max(0.0,v)*dt
        if fwd_dist>1.5 or (fwd_dist>0.8 and abs(hitch)<6):
            phase='rev'
        else:
            return (0.0,0.8,look)
    if abs(hitch)>45:
        phase='fwd'; fwd_dist=0.0
        return (0.0,0.8,look)
    rig=obs.get('rig',{}) or {}
    th=rig.get('trailer_heading_deg',-hitch)
    rd=180.0+th
    aim=None; close=False; info=''
    try:
        cam=(obs.get('views',{}) or {}).get('camera')
        if cam:
            ox,oy=cam.get('origin',[0,0])
            corners=cam.get('target_corners') or []
            walls=cam.get('walls') or []
            pts=[]
            for w in walls:
                r=math.radians(wrap(w[0]-rd))
                pts.append((w[1]*math.cos(r),w[1]*math.sin(r)))
            rc=3.0; lc=3.0
            for x,y in pts:
                if -0.3<x<2.5:
                    if y>0: rc=min(rc,y)
                    else: lc=min(lc,-y)
            offset=(rc-lc)/2.0
            lat=clamp(-15.0*offset,-15,15)
            if len(corners)>=2:
                cps=[(ox+c[1]*math.cos(math.radians(c[0])),oy+c[1]*math.sin(math.radians(c[0]))) for c in corners]
                cx=sum(p[0] for p in cps)/len(cps); cy=sum(p[1] for p in cps)/len(cps)
                b=math.degrees(math.atan2(cy-oy,cx-ox))
                dist=math.hypot(cx-ox,cy-oy)
                aim=wrap(rd-b)
                if dist<2.5: close=True
                if rc<1.1 or lc<1.1: aim+=0.5*lat
                info='bay d=%.1f'%dist
            else:
                best=None
                for a in range(-45,46,3):
                    ar=math.radians(a)
                    free=9.0
                    for x,y in pts:
                        px=x*math.cos(ar)+y*math.sin(ar)
                        py=-x*math.sin(ar)+y*math.cos(ar)
                        if px>1.5 and abs(py)<0.95:
                            free=min(free,px)
                    sc=free-0.03*abs(a)
                    if best is None or sc>best[0]: best=(sc,a)
                aim_gap=-best[1]
                aim=aim_gap+lat
                info='gap=%d rc=%.2f lc=%.2f lat=%.1f'%(aim_gap,rc,lc,lat)
    except Exception as e:
        aim=None; info='err %s'%e
    if aim is not None:
        aim_f=0.7*aim_f+0.3*aim
    gain=0.5 if close else 1.0
    target=clamp(gain*aim_f,-30,30)
    steer=clamp(-0.75*target+1.8*(hitch-target),-34,34)
    if t-last_print>1.5:
        last_print=t
        print('t=%.1f h=%.1f aim=%.1f tgt=%.1f st=%.1f %s'%(t,hitch,aim_f,target,steer,info))
    return (steer,-0.9,look)

