import math

phase='rev'
fwd_dist=0.0
rev_dist=0.0
aim_f=None
last_print=-10
last_steer=0.0
s_f=None

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(x,lo,hi):
    return max(lo,min(hi,x))

def fit(pts):
    n=len(pts)
    if n<3: return None
    mx=sum(p[0] for p in pts)/n; my=sum(p[1] for p in pts)/n
    sxx=sum((p[0]-mx)**2 for p in pts)
    if sxx<0.5: return None
    b=sum((p[0]-mx)*(p[1]-my) for p in pts)/sxx
    return (my-b*mx,b)

def ff(h):
    r=math.radians(h)
    return math.degrees(math.atan(2.75*math.sin(r)/(2.6+1.05*math.cos(r))))

def control(obs):
    global phase,fwd_dist,rev_dist,aim_f,last_print,last_steer,s_f
    hitch=obs.get('hitch_deg',0.0) or 0.0
    dt=obs.get('dt',0.1) or 0.1
    v=(obs.get('motion',{}) or {}).get('v_mps',0.0) or 0.0
    t=obs.get('t',0)
    look=-23
    if phase=='fwd':
        fwd_dist+=max(0.0,v)*dt
        if fwd_dist>1.2 or abs(hitch)<10:
            phase='rev'
        else:
            return (0.0,0.7,look)
    if abs(hitch)>50:
        phase='fwd'; fwd_dist=0.0
        return (0.0,0.7,look)
    rev_dist+=max(0.0,-v)*dt
    rig=obs.get('rig',{}) or {}
    th=rig.get('trailer_heading_deg',-hitch)
    rd=180.0+th
    aim=None; info=''
    try:
        cam=(obs.get('views',{}) or {}).get('camera')
        if cam:
            walls=cam.get('walls') or []
            corners=cam.get('target_corners') or []
            R=[];L=[]
            for w in walls:
                r=math.radians(wrap(w[0]-rd))
                X=w[1]*math.cos(r); Y=w[1]*math.sin(r)
                if 0.3<X<7.0:
                    (R if Y>0 else L).append((X,Y))
            fr=fit(R); fl=fit(L)
            s=None; ac=None
            if fr and fl:
                sr=math.degrees(math.atan(fr[1])); sl=math.degrees(math.atan(fl[1]))
                if abs(sr-sl)<15:
                    s=(sr+sl)/2; ac=(fr[0]+fl[0])/2
                elif len(R)>=len(L):
                    s=sr; ac=fr[0]-2.4
                else:
                    s=sl; ac=fl[0]+2.4
            elif fr:
                s=math.degrees(math.atan(fr[1])); ac=fr[0]-2.4
            elif fl:
                s=math.degrees(math.atan(fl[1])); ac=fl[0]+2.4
            if s is not None:
                s=clamp(s,-45,60)
                s_f=s if s_f is None else 0.7*s_f+0.3*s
            sv=s_f if s_f is not None else 0.0
            if len(corners)>=2:
                cps=[]
                for c in corners:
                    r=math.radians(wrap(c[0]-rd))
                    cps.append((c[1]*math.cos(r),c[1]*math.sin(r)))
                Xc=sum(p[0] for p in cps)/len(cps); Yc=sum(p[1] for p in cps)/len(cps)
                lat=Yc-math.tan(math.radians(sv))*Xc
                Lh=max(Xc,3.0)
                aim=sv+clamp(math.degrees(math.atan2(lat,Lh)),-25,25)
                info='bay X=%.1f Y=%.1f lat=%.2f s=%.1f'%(Xc,Yc,lat,sv)
            elif ac is not None:
                aim=sv+clamp(math.degrees(math.atan2(ac,6.0)),-25,25)
                info='cor s=%.1f ac=%.2f nR=%d nL=%d'%(sv,ac,len(R),len(L))
    except Exception as e:
        aim=None; info='err %s'%e
    if aim is not None:
        aim_f=aim if aim_f is None else 0.6*aim_f+0.4*aim
    if aim_f is None:
        return (last_steer,-0.6,look)
    ht=clamp(-1.1*aim_f,-35,35)
    steer=clamp(ff(ht)+1.5*(hitch-ht),-34,34)
    if rev_dist<0.4:
        steer=clamp(steer,-8,8)
    last_steer=steer
    if t-last_print>1.5:
        last_print=t
        print('t=%.1f h=%.1f aim=%.1f ht=%.1f st=%.1f %s'%(t,hitch,aim_f,ht,steer,info))
    return (steer,-0.8,look)

