import math
X=0.0;Y=0.0;PSI=0.0
grid={}
mode='fwd'
fstart=None
flen=2.0
seq=[64,150,64,-64,-150,-64]
li=0
hold=0.0
lastp=-10.0
nf=0
hd_last=0.0

def cl(v,a,b):
    return a if v<a else (b if v>b else v)

def wv(x,y):
    c=math.cos(PSI);s=math.sin(PSI)
    return X+x*c-y*s, Y+x*s+y*c

def vw(x,y):
    dx=x-X;dy=y-Y;c=math.cos(PSI);s=math.sin(PSI)
    return dx*c+dy*s, -dx*s+dy*c

def fit(ps):
    n=len(ps)
    if n==0: return None
    ma=sum(p[0] for p in ps)/n;ml=sum(p[1] for p in ps)/n
    va=sum((p[0]-ma)**2 for p in ps)
    if n>=3 and va>0.3:
        sl=sum((p[0]-ma)*(p[1]-ml) for p in ps)/va
    else:
        sl=0.0
    sl=cl(sl,-1.0,1.0)
    return (ml+sl*(1.5-ma), sl)

def control(obs):
    global X,Y,PSI,mode,fstart,flen,li,hold,lastp,nf,hd_last
    dt=obs.get('dt') or 0.1
