    if n%10==0:
        print('t%.1f h%.1f hd%.1f a%.1f maxf%.2f f0%.2f np%d'%(obs['t'],hitch,hdes,alpha_f,maxf,fr[12],len(pts)))
    return (steer,sp,look)

