                br=math.radians(b)
                px=ox+d*math.cos(br);py=oy+d*math.sin(br)
                wx=X+px*c-py*s;wy=Y+px*s+py*c
                MAP[(round(wx*10),round(wy*10))]=(wx,wy)
        except Exception: pass
    dead=[];pts=[]
    for k,(wx,wy) in MAP.items():
