    if rr<0.3 and steer<0: steer=max(steer,-45.0*cl((rr-0.08)/0.22,0.0,1.0))
    if n%10==0:
        print('t%.1f h%.1f hd%.1f e%.0f st%.0f fl%.2f fr%.2f rl%.2f rr%.2f tL%.2f tR%.2f dist%.1f al%.1f'%(obs['t'],h,hdes,e,steer,fl,fr,rl,rr,tL,tR,dist,along))
    if not halt and (min(rl,rr,tL,tR)<0.06 or abs(h)>40 or (TW is not None and along<-0.6)):
        halt=True
        print('HALT t%.1f h%.1f fl%.2f fr%.2f rl%.2f rr%.2f tL%.2f tR%.2f al%.1f'%(obs['t'],h,fl,fr,rl,rr,tL,tR,along))
        try: wake('halted near rail / limit')
        except Exception: pass
    if halt:
        return (st,0.0,look)
    sp=-0.25
    if abs(h-hdes)>10 or min(fl,fr,rl,rr,tL,tR)<0.3: sp=-0.18
    return (steer,sp,look)

